import { test, expect } from '@playwright/test'
import {
  loginAsAdminOnce,
  waitForPageLoading,
  gotoHashPath,
  collectAppRoutes
} from '../fixtures/auth-helpers.js'

/**
 * 预售资金新页面浏览器 UI 实测（禅道 #1413 #1415）
 *
 * 目标：不只是接口通，而是页面真的能渲染、能列表化、能打开详情。
 * 走 nginx 8098 部署站点（不启 dev server）。
 */

const MODULES = [
  {
    name: '监管机构管理',
    filePath: 'supervision/account/regulatorOrg/index',
    detailPath: 'supervision/account/regulatorOrg/detail',
    expectHeaders: ['机构编码', '机构名称', '统一社会信用代码', '机构类型'],
    apiHint: '/prefund/regulatorOrg/page'
  },
  {
    name: '监管主账户',
    filePath: 'supervision/account/mainAccount/index',
    detailPath: 'supervision/account/mainAccount/detail',
    expectHeaders: ['账户名称', '账户类型', '监管账号', '承办银行'],
    apiHint: '/prefund/mainAccount/page'
  },
  {
    name: '监管账户',
    filePath: 'supervision/account/regulatoryAccountNew/index',
    detailPath: 'supervision/account/regulatoryAccountNew/detail',
    expectHeaders: ['开户通知书号', '开发企业', '项目名称', '监管账户'],
    apiHint: '/prefund/regulatoryAccountNew/page'
  },
  {
    name: '监管协议签署',
    filePath: 'supervision/account/superviseAgreementNew/index',
    detailPath: 'supervision/account/superviseAgreementNew/detail',
    expectHeaders: ['协议号', '项目名称', '监管项目', '开发企业'],
    apiHint: '/prefund/superviseAgree/page'
  }
]

test.describe('预售资金新页面 UI 实测', () => {
  test.describe.configure({ mode: 'serial' })

  test.beforeEach(async ({ page }) => {
    await loginAsAdminOnce(page)
  })

  for (const mod of MODULES) {
    test(`${mod.name} - 菜单已注册且列表页可渲染`, async ({ page }) => {
      const routes = await collectAppRoutes(page)
      const matched = routes.filter((r) => r.filePath === mod.filePath)
      expect(
        matched.length,
        `菜单未注册或未授权：${mod.filePath}。当前已注册路由含 supervision/account 的有：${
          routes.filter((r) => String(r.filePath || '').includes('supervision/account')).map((r) => r.filePath).join(', ') || '（无）'
        }`
      ).toBeGreaterThan(0)

      const listRoute = matched.find((r) => !String(r.path).includes(':tableid')) || matched[0]
      await gotoHashPath(page, listRoute.path)
      await waitForPageLoading(page)

      // 列表页核心：搜索区 + 表格 + 表头
      const table = page.locator('.zs-table, .el-table').first()
      await expect(table, `${mod.name} 列表表格未渲染`).toBeVisible({ timeout: 20000 })

      const headerText = await table.locator('thead').innerText().catch(() => '')
      for (const h of mod.expectHeaders) {
        expect(headerText, `${mod.name} 表头缺少「${h}」，实际：${headerText.replace(/\s+/g, ' ')}`).toContain(h)
      }
    })

    test(`${mod.name} - 列表正常返回（无服务器异常）`, async ({ page }) => {
      const routes = await collectAppRoutes(page)
      const listRoute = routes.find((r) => r.filePath === mod.filePath && !String(r.path).includes(':tableid'))
      if (!listRoute) test.skip()

      // 监听列表接口，确认 HTTP 200 且 code=200
      const respPromise = page.waitForResponse(
        (r) => r.url().includes(mod.apiHint) && r.request().method() === 'POST',
        { timeout: 30000 }
      )
      await gotoHashPath(page, listRoute.path)
      const resp = await respPromise
      const body = await resp.json().catch(() => ({}))
      expect(resp.status(), `${mod.name} 列表接口 HTTP 异常`).toBe(200)
      expect(body.code, `${mod.name} 列表接口业务异常: ${body.msg || ''}`).toBe(200)
    })
  }

  test('监管账户 - 有数据行时可点入详情并渲染表单', async ({ page }) => {
    const routes = await collectAppRoutes(page)
    const listRoute = routes.find(
      (r) => r.filePath === 'supervision/account/regulatoryAccountNew/index' && !String(r.path).includes(':tableid')
    )
    if (!listRoute) test.skip()

    await gotoHashPath(page, listRoute.path)
    await waitForPageLoading(page)

    const table = page.locator('.zs-table, .el-table').first()
    await expect(table).toBeVisible({ timeout: 20000 })

    // 第一列是 link 型（开户通知书号），点击进详情
    const firstLink = table.locator('tbody tr').first().locator('a, .el-link, .cell-link').first()
    const linkCount = await firstLink.count()
    if (linkCount === 0) test.skip()

    await firstLink.click()
    await page.waitForURL((url) => /\/\d+/.test(url.hash), { timeout: 20000 }).catch(() => {})
    await waitForPageLoading(page)

    // 详情页必须有表单（zs-form / el-form）与监管账户关键字段
    const form = page.locator('.zs-form, form.el-form').first()
    await expect(form, '监管账户详情页表单未渲染').toBeVisible({ timeout: 20000 })

    const detailText = await page.locator('.detail-container').first().innerText().catch(() => '')
    expect(detailText, '详情页未展示开户编号').toMatch(/开户|监管|项目/)
  })
})

