  const dictResponses = []
  page.on('response', async (r) => {
    if (r.url().includes('dictData/listByType')) {
      const body = await r.json().catch(() => null)
      dictResponses.push({
        status: r.status(),
        req: r.request().postData(),
        count: body?.data?.length ?? -1,
        code: body?.code
      })
    }
  })

  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find((r) => r.filePath === 'supervision/account/regulatorOrg/index' && !String(r.path).includes(':tableid'))
