  await waitForPageLoading(page)

  await page.getByText('新增', { exact: true }).first().click()
  await waitForPageLoading(page)
  await page.waitForTimeout(3000)

  const vmState = await page.evaluate(() => {
    const app = document.querySelector('#app')?.__vue__
    let comp = app
    // 向下找带 orgTypeOptions 的组件
    const walk = (c, depth = 0) => {
      if (!c || depth > 8) return null
      if (c.$data && 'orgTypeOptions' in c.$data) return c
      for (const child of c.$children || []) {
        const found = walk(child, depth + 1)
        if (found) return found
      }
      return null
    }
    comp = walk(app)
    if (!comp) return { found: false }
    return {
      found: true,
      orgTypeOptions: JSON.parse(JSON.stringify(comp.orgTypeOptions || [])),
      statusOptionsLen: (comp.statusOptions || []).length,
      formMode: comp.formMode,
      cachedDictKeys: [...(window.__cachedDictKeys || [])]
    }
  })

  console.log('DICT_RESPONSES=', JSON.stringify(dictResponses, null, 2))
  console.log('VM_STATE=', JSON.stringify(vmState, null, 2))
})

